INSERT INTO public.cargo_agent_knowledge (content, metadata) VALUES
('Cash to Master service at Curacao. LBH Curacao arranges cash delivery directly to the vessel master. Delivery fee: $350 USD flat fee. Bank charges: 6.75% of the total cash amount requested. Example: Cash to Master $2,000 USD = $350 delivery fee + $135 bank charges = $485 total agent cost. Maximum amount subject to availability. Required information: vessel name, amount requested in USD, ETA, and master full name. Cash is delivered in USD. Advance notice of minimum 24 hours required.', '{"category": "crew_change", "topic": "cash_to_master"}'::jsonb),
('Garbage removal service at Willemstad Curacao port. LBH Curacao coordinates collection of all MARPOL garbage categories including food waste, plastics, operational waste, and hazardous waste. Service arranged upon vessel arrival or departure. Vessel must provide completed Garbage Record Book entry. Rate: on request depending on volume and type. Typical turnaround: same day if requested before 12:00. Contact agent minimum 12 hours in advance with estimated garbage type and quantity.', '{"category": "crew_change", "topic": "garbage_removal"}'::jsonb),
('LBH Curacao standard agency tariffs. Loading or Discharging: coordination fee $1,650 for first 2 days, $225 each additional day. Cargo documentation loading only $100 per BL. ISPS formalities $100 per port call. Communication expenses $45 per day. Car expenses $75. Protecting agent: $950 for first 2 days, $200 each additional day. Bunkering offshore: $750. Bunkering in port: $950 first 2 days, $175 each additional day. Sample handling $85. Crew change offshore: $950 up to 10 pax, $1,150 from 10 pax. Crew change in port: $750 up to 10 pax, $950 from 10 pax. Fee per crewmember $95. Spares handling offshore: $950 up to 10 AWB, $1,150 from 10 AWB. Repairs: $1,650 for first 3 days, $275 each additional day.', '{"category": "port_formalities", "topic": "agency_fees"}'::jsonb);
